def transform(grid, marker_pos):
    h, w = len(grid), len(grid[0])

    # Find main pattern (all non-zero except marker)
    def get_nonzero_positions(g):
        return [(i, j, g[i][j]) for i in range(len(g)) for j in range(len(g[0])) if g[i][j] != 0]

    all_cells = get_nonzero_positions(grid)

    # Find marker (the isolated single-cell component with value matching what we expect)
    # Actually from Demo 1, marker has value 5 and is isolated
    # But let's find it by being alone vs part of a group

    # For now, assume marker_pos is given
    marker_vals = {(m[0], m[1]): grid[m[0]][m[1]] for m in [marker_pos]}

    # Main pattern cells
    main_cells = {pos: val for pos, val in all_cells if pos not in marker_vals}

    # Shift (+5, +3)
    shifted_main = {(r+5, c+3): val for (r, c), val in main_cells.items()}

    # Build output, skipping cells that would hit marker
    output = {}
    for pos, val in shifted_main.items():
        if pos != marker_pos:  # Skip if lands on marker
            output[pos] = val

    # Return grid
    result = [[0]*w for _ in range(h)]
    for pos, val in list(output.items()):
        r, c = pos
        result[r][c] = val

    return result

